1	import { existsSync, readFileSync } from "node:fs";
2	import { resolvePaperclipConfigPath, resolvePaperclipEnvPath } from "./paths.js";
3	import type { BindMode, DeploymentExposure, DeploymentMode } from "@paperclipai/shared";
4	
5	import { parse as parseEnvFileContents } from "dotenv";
6	
7	type UiMode = "none" | "static" | "vite-dev";
8	
9	type ExternalPostgresInfo = {
10	  mode: "external-postgres";
11	  connectionString: string;
12	};
13	
14	type EmbeddedPostgresInfo = {
15	  mode: "embedded-postgres";
16	  dataDir: string;
17	  port: number;
18	};
19	
20	type StartupBannerOptions = {
21	  bind: BindMode;
22	  host: string;
23	  deploymentMode: DeploymentMode;
24	  deploymentExposure: DeploymentExposure;
25	  authReady: boolean;
26	  requestedPort: number;
27	  listenPort: number;
28	  uiMode: UiMode;
29	  db: ExternalPostgresInfo | EmbeddedPostgresInfo;
30	  migrationSummary: string;
31	  heartbeatSchedulerEnabled: boolean;
32	  heartbeatSchedulerIntervalMs: number;
33	  databaseBackupEnabled: boolean;
34	  databaseBackupIntervalMinutes: number;
35	  databaseBackupRetentionDays: number;
36	  databaseBackupDir: string;
37	};
38	
39	const ansi = {
40	  reset: "\x1b[0m",
41	  bold: "\x1b[1m",
42	  dim: "\x1b[2m",
43	  cyan: "\x1b[36m",
44	  green: "\x1b[32m",
45	  yellow: "\x1b[33m",
46	  magenta: "\x1b[35m",
47	  blue: "\x1b[34m",
48	};
49	
50	function color(text: string, c: keyof typeof ansi): string {
51	  return `${ansi[c]}${text}${ansi.reset}`;
52	}
53	
54	function row(label: string, value: string): string {
55	  return `${color(label.padEnd(16), "dim")} ${value}`;
56	}
57	
58	function redactConnectionString(raw: string): string {
59	  try {
60	    const u = new URL(raw);
61	    const user = u.username || "user";
62	    const auth = `${user}:***@`;
63	    return `${u.protocol}//${auth}${u.host}${u.pathname}`;
64	  } catch {
65	    return "<invalid DATABASE_URL>";
66	  }
67	}
68	
69	function resolveAgentJwtSecretStatus(
70	  envFilePath: string,
71	): {
72	  status: "pass" | "warn";
73	  message: string;
74	} {
75	  const envValue = process.env.PAPERCLIP_AGENT_JWT_SECRET?.trim();
76	  if (envValue) {
77	    return {
78	      status: "pass",
79	      message: "set",
80	    };
81	  }
82	
83	  if (existsSync(envFilePath)) {
84	    const parsed = parseEnvFileContents(readFileSync(envFilePath, "utf-8"));
85	    const fileValue = typeof parsed.PAPERCLIP_AGENT_JWT_SECRET === "string" ? parsed.PAPERCLIP_AGENT_JWT_SECRET.trim() : "";
86	    if (fileValue) {
87	      return {
88	        status: "warn",
89	        message: `found in ${envFilePath} but not loaded`,
90	      };
91	    }
92	  }
93	
94	  return {
95	    status: "warn",
96	    message: "missing (run `pnpm paperclipai onboard`)",
97	  };
98	}
99	
100	export function printStartupBanner(opts: StartupBannerOptions): void {
101	  const baseHost = opts.host === "0.0.0.0" ? "localhost" : opts.host;
102	  const baseUrl = `http://${baseHost}:${opts.listenPort}`;
103	  const apiUrl = `${baseUrl}/api`;
104	  const uiUrl = opts.uiMode === "none" ? "disabled" : baseUrl;
105	  const configPath = resolvePaperclipConfigPath();
106	  const envFilePath = resolvePaperclipEnvPath();
107	  const agentJwtSecret = resolveAgentJwtSecretStatus(envFilePath);
108	
109	  const dbMode =
110	    opts.db.mode === "embedded-postgres"
111	      ? color("embedded-postgres", "green")
112	      : color("external-postgres", "yellow");
113	  const uiMode =
114	    opts.uiMode === "vite-dev"
115	      ? color("vite-dev-middleware", "cyan")
116	      : opts.uiMode === "static"
117	        ? color("static-ui", "magenta")
118	        : color("headless-api", "yellow");
119	
120	  const portValue =
121	    opts.requestedPort === opts.listenPort
122	      ? `${opts.listenPort}`
123	      : `${opts.listenPort} ${color(`(requested ${opts.requestedPort})`, "dim")}`;
124	
125	  const dbDetails =
126	    opts.db.mode === "embedded-postgres"
127	      ? `${opts.db.dataDir} ${color(`(pg:${opts.db.port})`, "dim")}`
128	      : redactConnectionString(opts.db.connectionString);
129	
130	  const heartbeat = opts.heartbeatSchedulerEnabled
131	    ? `enabled ${color(`(${opts.heartbeatSchedulerIntervalMs}ms)`, "dim")}`
132	    : color("disabled", "yellow");
133	  const dbBackup = opts.databaseBackupEnabled
134	    ? `enabled ${color(`(every ${opts.databaseBackupIntervalMinutes}m, keep ${opts.databaseBackupRetentionDays}d)`, "dim")}`
135	    : color("disabled", "yellow");
136	
137	  const art = [
138	    color("██████╗  █████╗ ██████╗ ███████╗██████╗  ██████╗██╗     ██╗██████╗ ", "cyan"),
139	    color("██╔══██╗██╔══██╗██╔══██╗██╔════╝██╔══██╗██╔════╝██║     ██║██╔══██╗", "cyan"),
140	    color("██████╔╝███████║██████╔╝█████╗  ██████╔╝██║     ██║     ██║██████╔╝", "cyan"),
141	    color("██╔═══╝ ██╔══██║██╔═══╝ ██╔══╝  ██╔══██╗██║     ██║     ██║██╔═══╝ ", "cyan"),
142	    color("██║     ██║  ██║██║     ███████╗██║  ██║╚██████╗███████╗██║██║     ", "cyan"),
143	    color("╚═╝     ╚═╝  ╚═╝╚═╝     ╚══════╝╚═╝  ╚═╝ ╚═════╝╚══════╝╚═╝╚═╝     ", "cyan"),
144	  ];
145	
146	  const lines = [
147	    "",
148	    ...art,
149	    color("  ───────────────────────────────────────────────────────", "blue"),
150	    row("Mode", `${dbMode}  |  ${uiMode}`),
151	    row("Deploy", `${opts.deploymentMode} (${opts.deploymentExposure})`),
152	    row("Bind", `${opts.bind} ${color(`(${opts.host})`, "dim")}`),
153	    row("Auth", opts.authReady ? color("ready", "green") : color("not-ready", "yellow")),
154	    row("Server", portValue),
155	    row("API", `${apiUrl} ${color(`(health: ${apiUrl}/health)`, "dim")}`),
156	    row("UI", uiUrl),
157	    row("Database", dbDetails),
158	    row("Migrations", opts.migrationSummary),
159	    row(
160	      "Agent JWT",
161	      agentJwtSecret.status === "pass"
162	        ? color(agentJwtSecret.message, "green")
163	        : color(agentJwtSecret.message, "yellow"),
164	    ),
165	    row("Heartbeat", heartbeat),
166	    row("DB Backup", dbBackup),
167	    row("Backup Dir", opts.databaseBackupDir),
168	    row("Config", configPath),
169	    agentJwtSecret.status === "warn"
170	      ? color("  ───────────────────────────────────────────────────────", "yellow")
171	      : null,
172	    color("  ───────────────────────────────────────────────────────", "blue"),
173	    "",
174	  ];
175	
176	  console.log(lines.filter((line): line is string => line !== null).join("\n"));
177	}
